  await supervisor.getByRole('button',{name:'Continue',exact:true}).click();await supervisor.getByRole('button',{name:'Add task step and hazard',exact:true}).click();await supervisor.getByLabel('Task step',{exact:true}).fill('SYNTHETIC unload materials');await supervisor.getByLabel('Hazard or concern',{exact:true}).fill('SYNTHETIC shared delivery route');await supervisor.getByLabel('Control or precaution',{exact:true}).fill('SYNTHETIC discuss route before delivery');await supervisor.getByLabel('Responsible for this control',{exact:true}).selectOption(actors.WORKER.id);await supervisor.getByLabel('Unresolved concern — keep in Actions',{exact:true}).uncheck();await saved(supervisor)
  await supervisor.getByRole('button',{name:'Continue',exact:true}).click();await supervisor.getByLabel('What was discussed in the briefing?',{exact:true}).fill('SYNTHETIC morning route discussion');await supervisor.getByRole('checkbox',{name:workerName,exact:true}).check();await saved(supervisor);await supervisor.getByRole('button',{name:'Record briefing version',exact:true}).click();await expect(supervisor.getByRole('button',{name:'Revise brief',exact:true})).toBeVisible()
