  await worker.getByLabel('Photo file',{exact:true}).setInputFiles({name:'SYNTHETIC-workday-packing.jpg',mimeType:'image/jpeg',buffer:photo});await worker.getByLabel('Photo caption',{exact:true}).fill('SYNTHETIC orange packing marker at east bay');await worker.getByRole('button',{name:'Upload photo',exact:true}).click();await expect(worker.getByRole('status').filter({hasText:'Photo saved and retained.'})).toBeVisible();await worker.reload();await expect(worker.getByRole('img',{name:'SYNTHETIC orange packing marker at east bay',exact:true})).toBeVisible()
